// Demo data: clips 衣夾-02～08, a garment library, sessions in progress and past records, all with
// is_demo = true. It is never written on startup; `make seed` (scripts/seed-demo.ts) writes it once
// and POST /clothes/demo/reset rebuilds it. 衣夾-01 is the real clip and gets no demo data.
// Ids are generated by PostgreSQL, so the seed refers to clips and garments by their (unique) names.
import { dbClient } from '../db/client';
import type { Material } from './prediction';

const MIN = 60000;
const DAY_MS = 24 * 60 * MIN;
const TAIPEI_MS = 8 * 60 * MIN;

type Style = 'tee' | 'shirt' | 'tank' | 'pants' | 'towel';
export interface DemoSeed {
  clips: { name: string }[];
  garments: { name: string; style: Style; color: string; material: Material }[];
  sessions: {
    clip: string; garment: string; started_at: Date; predicted_min: number;  // clip and garment by name
    ended_at: Date | null; outcome: 'dry' | 'early' | null; actual_min: number | null;
  }[];
}

const CLIPS = ['衣夾-02', '衣夾-03', '衣夾-04', '衣夾-05', '衣夾-06', '衣夾-07', '衣夾-08'];

// Pure, so tests can check it. Times are relative to `now`.
export function demoSeed(now: number): DemoSeed {
  const clips = CLIPS.map((name) => ({ name }));
  const garments: DemoSeed['garments'] = [
    { name: '白色班服', style: 'tee', color: '#F2F1EC', material: '棉' },
    { name: '牛仔褲', style: 'pants', color: '#4A6FA5', material: '牛仔布' },
    { name: '運動背心', style: 'tank', color: '#2A2B30', material: '聚酯纖維' },
    { name: '亞麻襯衫', style: 'shirt', color: '#D8CBB0', material: '麻' },
    { name: '黃色浴巾', style: 'towel', color: '#E9C46A', material: '毛巾布' },
    { name: '黑色運動褲', style: 'pants', color: '#2A2B30', material: '聚酯纖維' },
    { name: '條紋毛巾', style: 'towel', color: '#4A6FA5', material: '毛巾布' },
    { name: '灰色帽 T', style: 'shirt', color: '#9AA3AD', material: '棉' },
  ];
  // [clip, garment, elapsed min, remaining min] — drying right now.
  const active: [string, string, number, number][] = [
    ['衣夾-02', '牛仔褲', 205, 295], ['衣夾-03', '運動背心', 110, 40], ['衣夾-04', '亞麻襯衫', 130, 185], ['衣夾-05', '黃色浴巾', 80, 345],
  ];
  // [days ago, start hour (Taipei), garment, actual min (null = taken in early), predicted min]
  const past: [number, number, string, number | null, number][] = [
    [1, 9.5, '白色班服', 280, 265], [1, 10, '牛仔褲', 455, 420], [2, 8, '條紋毛巾', 320, 340], [3, 13, '運動背心', 110, 115],
    [4, 9, '亞麻襯衫', 350, 310], [5, 9, '白色班服', 295, 300], [6, 10, '黑色運動褲', 150, 140], [7, 11, '條紋毛巾', 335, 320],
    [8, 9, '白色班服', 270, 290], [9, 14, '運動背心', 105, 100], [10, 9, '灰色帽 T', 300, 285], [11, 10, '黑色運動褲', null, 160],
    [12, 9, '牛仔褲', 470, 450], [13, 8, '灰色帽 T', 275, 290],
  ];
  const todayStart = Math.floor((now + TAIPEI_MS) / DAY_MS) * DAY_MS - TAIPEI_MS;
  const sessions: DemoSeed['sessions'] = [
    ...active.map(([clip, garment, elapsed, left]) => ({
      clip, garment, started_at: new Date(now - elapsed * MIN), predicted_min: elapsed + left,
      ended_at: null, outcome: null, actual_min: null,
    })),
    ...past.map(([days, hour, garment, actual, predicted], i) => {
      const started = todayStart - days * DAY_MS + hour * 60 * MIN;
      // Taken in early: put away about halfway through.
      const ended = started + (actual ?? Math.round(predicted / 2)) * MIN;
      return {
        clip: CLIPS[i % CLIPS.length], garment, started_at: new Date(started),
        predicted_min: predicted, ended_at: new Date(ended), outcome: actual == null ? 'early' as const : 'dry' as const,
        actual_min: actual,
      };
    }),
  ];
  return { clips, garments, sessions };
}

// Inserts the rows and looks the generated UUIDs up by name for the sessions.
async function writeSeed(tx: any, seed: DemoSeed) {
  const clipIds = new Map<string, string>();
  const garmentIds = new Map<string, string>();
  for (const clip of seed.clips) {
    const rows = await tx`INSERT INTO clips (name, is_demo) VALUES (${clip.name}, true) RETURNING id`;
    clipIds.set(clip.name, rows[0].id);
  }
  for (const g of seed.garments) {
    const rows = await tx`
      INSERT INTO garments (name, style, color, material, is_demo) VALUES (${g.name}, ${g.style}, ${g.color}, ${g.material}, true) RETURNING id`;
    garmentIds.set(g.name, rows[0].id);
  }
  for (const s of seed.sessions) {
    await tx`
      INSERT INTO drying_sessions (clip_id, garment_id, started_at, predicted_min, ended_at, outcome, actual_min, is_demo)
      VALUES (${clipIds.get(s.clip)}::uuid, ${garmentIds.get(s.garment)}::uuid, ${s.started_at}, ${s.predicted_min},
        ${s.ended_at}, ${s.outcome}, ${s.actual_min}, true)`;
  }
}

function database() {
  if (!dbClient.isConnected()) throw new Error('Database unavailable');
  return dbClient.sql;
}

// Writes the demo data once. Returns false (and writes nothing) when demo clips already exist.
export async function seedDemoData(now = Date.now()): Promise<boolean> {
  return database().begin(async (tx: any) => {
    const existing = await tx`SELECT 1 FROM clips WHERE is_demo LIMIT 1`;
    if (existing.length) return false;
    await writeSeed(tx, demoSeed(now));
    return true;
  });
}

// Deletes every demo row and writes a fresh set relative to now. Real rows are not touched.
export async function resetDemoData(now = Date.now()): Promise<void> {
  await database().begin(async (tx: any) => {
    await tx`DELETE FROM drying_sessions WHERE is_demo`;
    await tx`DELETE FROM garments WHERE is_demo`;
    await tx`DELETE FROM clips WHERE is_demo`;
    await writeSeed(tx, demoSeed(now));
  });
}
